use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let year = input.as_i64().unwrap();
    let month = input.as_i64().unwrap();
    let day = input.as_i64().unwrap();
    let mut date = i64::from(year) as i64;
    let mut month = month as i64;
    let mut day = day as i64;
    while day > 0 {
        date += 1;
        if month == 2 {
            if date > 29 {
                date -= 29;
            }
        } else if month == 4 || month == 6 || month == 9 || month == 11 {
            if date > 30 {
                date -= 30;
            }
        } else if month == 2 && date > 28 {
            date -= 28;
        }
        month -= 1;
        day -= 1;
    }
    Value::from(date)
}
